1	package govflow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"sort"
8		"strconv"
9		"strings"
10	)
11	
12	// 投票提案相关错误。
13	var (
14		// ErrInvalidProposal：创建投票提案的参数非法（编号/成员/权重/时间/委托等）。
15		ErrInvalidProposal = errors.New("invalid voting proposal")
16		// ErrProposalNotFound 见 store.go。
17		// ErrProposalConflict：同编号提案已存在但内容或来源不同，或重复投票选择不同。
18		// ErrVoteRejected：投票被拒绝（时间窗口外、投票人无资格等）。
19		ErrVoteRejected = errors.New("vote rejected")
20		// ErrTallyRejected：计票被拒绝（截止时刻未到）。
21		ErrTallyRejected = errors.New("tally rejected")
22	)
23	
24	// ---- 输入与对外视图 ----
25	
26	// VoteMember 是创建投票提案时提交的一名成员及其原始权重。
27	type VoteMember struct {
28		ID     string `json:"id"`
29		Weight int64  `json:"weight"`
30	}
31	
32	// Delegation 表示 From 把投票权委托给 To。委托可以继续转交，
33	// 最终未再委托的人代表沿途所有成员投票。
34	type Delegation struct {
35		From string `json:"from"`
36		To   string `json:"to"`
37	}
38	
39	// CreateVoteInput 是创建一项投票提案的完整输入。
40	type CreateVoteInput struct {
41		ID          string
42		Members     []VoteMember
43		Delegations []Delegation
44		Quorum      int64
45		StartAt     int64
46		Deadline    int64
47		TimelockEnd int64
48		Actions     []string
49	}
50	
51	// MemberView 是查询时展示的一名成员：委托路径、最终代表与原始权重。
52	type MemberView struct {
53		ID       string   `json:"id"`
54		Weight   int64    `json:"weight"`
55		Path     []string `json:"path"`      // 从本人到最终代表的完整编号链（含首尾）
56		Delegate string   `json:"delegate"`  // 最终代表
57		Direct   string   `json:"direct_to"` // 直接委托对象；未委托为空串
58	}
59	
60	// BallotView 是查询时展示的一张已投出的票。
61	type BallotView struct {
62		Representative string `json:"representative"`
63		Weight         int64  `json:"weight"`
64		Support        bool   `json:"support"`
65		VotedAt        int64  `json:"voted_at"`
66	}
67	
68	// TallyResultView 是首次计票结论的查询视图；尚未计票时为 nil。
69	type TallyResultView struct {
70		ForWeight     int64 `json:"for_weight"`
71		AgainstWeight int64 `json:"against_weight"`
72		Turnout       int64 `json:"turnout"`
73		Quorum        int64 `json:"quorum"`
74		Passed        bool  `json:"passed"`
75		TalliedAt     int64 `json:"tallied_at"`
76	}
77	
78	// VoteProposalView 是一项投票提案的完整对外视图。
79	type VoteProposalView struct {
80		ID          string           `json:"id"`
81		Source      string           `json:"source"` // vote
82		State       string           `json:"state"`  // voting / passed / rejected / executed
83		Quorum      int64            `json:"quorum"`
84		StartAt     int64            `json:"start_at"`
85		Deadline    int64            `json:"deadline"`
86		TimelockEnd int64            `json:"timelock_end"`
87		Actions     []string         `json:"actions"`
88		TotalWeight int64            `json:"total_weight"`
89		Members     []MemberView     `json:"members"`
90		Ballots     []BallotView     `json:"ballots"`
91		Tally       *TallyResultView `json:"tally,omitempty"`
92	}
93	
94	// ---- 磁盘结构（JSON，版本仍为 1） ----
95	
96	type storedMember struct {
97		ID     string `json:"id"`
98		Weight int64  `json:"weight"`
99	}
100	
101	type storedDelegation struct {
102		From string `json:"from"`
103		To   string `json:"to"`
104	}
105	
106	// storedBallot 是一张已保存的票。四个字段都必须明确写出、非空且类型正确：
107	// representative 是 JSON 字符串，weight/voted_at 是 JSON 整数（int64 范围），
108	// support 必须是 JSON 布尔值。绝不能靠零值/默认值补出治理记录：
109	// 缺失或 null 的 support 不得被当作 false（反对票），缺失或 null 的
110	// voted_at 不得被当作 0（首次投票时间）。
111	//
112	// 标量字段先用 RawMessage 接住，使“字段缺失”与“显式 null/写错类型”在解码后
113	// 仍可区分：encoding/json 直接解进 bool/int64/string 时会把这三种情况都
114	// 折叠成零值。每个字段的“缺失/空值/类型不符”由 validateStoredBallot 判定。
115	type storedBallot struct {
116		Representative string `json:"representative"`
117		Weight         int64  `json:"weight"`
118		Support        bool   `json:"support"`
119		VotedAt        int64  `json:"voted_at"`
120	
121		representativeRaw json.RawMessage
122		weightRaw         json.RawMessage
123		supportRaw        json.RawMessage
124		votedAtRaw        json.RawMessage
125	}
126	
127	// ballotJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
128	type ballotJSONShape struct {
129		Representative json.RawMessage `json:"representative"`
130		Weight         json.RawMessage `json:"weight"`
131		Support        json.RawMessage `json:"support"`
132		VotedAt        json.RawMessage `json:"voted_at"`
133	}
134	
135	// UnmarshalJSON 保留字段是否出现及其原始写法（缺失为 nil、null 为 "null"），
136	// 供 validateStoredBallot 区分缺失、空值与类型不符。单个字段类型不符时这里
137	// 不返回错误（对应治理字段保持零值），以免解码器在不含提案编号/票据下标的
138	// 通用错误处提前失败；定位与判定统一交给 validateStoredBallot。
139	func (b *storedBallot) UnmarshalJSON(data []byte) error {
140		var shape ballotJSONShape
141		if err := json.Unmarshal(data, &shape); err != nil {
142			return err
143		}
144		b.representativeRaw, b.weightRaw = shape.Representative, shape.Weight
145		b.supportRaw, b.votedAtRaw = shape.Support, shape.VotedAt
146		// 仅当字段确实是目标类型时才填充治理字段；类型不符留待校验拒绝，
147		// 绝不能让错误类型悄悄落成零值并参与查询或计票。
148		if raw := shape.Representative; jsonValueType(raw) == "string" {
149			_ = json.Unmarshal(raw, &b.Representative)
150		}
151		if raw := shape.Weight; isInt64Number(raw) {
152			_ = json.Unmarshal(raw, &b.Weight)
153		}
154		if raw := shape.Support; jsonValueType(raw) == "boolean" {
155			_ = json.Unmarshal(raw, &b.Support)
156		}
157		if raw := shape.VotedAt; isInt64Number(raw) {
158			_ = json.Unmarshal(raw, &b.VotedAt)
159		}
160		return nil
161	}
162	
163	// MarshalJSON 只输出四个治理字段，RawMessage 状态（仅用于入站判定）不落盘。
164	func (b storedBallot) MarshalJSON() ([]byte, error) {
165		return json.Marshal(storedBallotOut{
166			Representative: b.Representative,
167			Weight:         b.Weight,
168			Support:        b.Support,
169			VotedAt:        b.VotedAt,
170		})
171	}
172	
173	// storedBallotOut 是票据的保存形状；字段名与保存格式逐字一致。
174	type storedBallotOut struct {
175		Representative string `json:"representative"`
176		Weight         int64  `json:"weight"`
177		Support        bool   `json:"support"`
178		VotedAt        int64  `json:"voted_at"`
179	}
180	
181	// mustStoreBallot 构造一张内存中的合法票据（投票成功路径使用）。
182	// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
183	// validateStoredBallot 判定时不会把本进程新建的票据误判为字段缺失。
184	func mustStoreBallot(representative string, weight int64, support bool, votedAt int64) storedBallot {
185		repRaw, _ := json.Marshal(representative)
186		wRaw, _ := json.Marshal(weight)
187		supRaw, _ := json.Marshal(support)
188		atRaw, _ := json.Marshal(votedAt)
189		return storedBallot{
190			Representative:    representative,
191			Weight:            weight,
192			Support:           support,
193			VotedAt:           votedAt,
194			representativeRaw: repRaw,
195			weightRaw:         wRaw,
196			supportRaw:        supRaw,
197			votedAtRaw:        atRaw,
198		}
199	}
200	
201	// validateStoredBallot 严格判定一张已保存票据的四个必填字段：
202	// 任一字段未写出、显式为 null 或 JSON 类型不符（support 不接受字符串/数字，
203	// weight/voted_at 不接受字符串/小数/指数等非整数）都返回带原因的错误。
204	// 明确写出的 false 是有效反对票；窗口允许时明确写出的 0 是有效投票时间，
205	// 这两种合法值不得当成缺失。index 是票据在提案中的下标（0 起），用于定位。
206	func validateStoredBallot(id string, index int, b *storedBallot) error {
207		check := func(field string, raw json.RawMessage, kind string, decode func() error) error {
208			switch {
209			case raw == nil:
210				return fmt.Errorf("voting proposal %q ballot %d field %q is missing", id, index, field)
211			case string(raw) == "null":
212				return fmt.Errorf("voting proposal %q ballot %d field %q is null", id, index, field)
213			default:
214				if err := decode(); err != nil {
215					return fmt.Errorf("voting proposal %q ballot %d field %q has wrong type: want %s, got %s",
216						id, index, field, kind, jsonValueType(raw))
217				}
218				return nil
219			}
220		}
221		if err := check("representative", b.representativeRaw, "string", func() error {
222			return json.Unmarshal(b.representativeRaw, new(string))
223		}); err != nil {
224			return err
225		}
226		if err := check("weight", b.weightRaw, "integer", func() error {
227			return json.Unmarshal(b.weightRaw, new(int64))
228		}); err != nil {
229			return err
230		}
231		if err := check("support", b.supportRaw, "boolean", func() error {
232			return json.Unmarshal(b.supportRaw, new(bool))
233		}); err != nil {
234			return err
235		}
236		if err := check("voted_at", b.votedAtRaw, "integer", func() error {
237			return json.Unmarshal(b.votedAtRaw, new(int64))
238		}); err != nil {
239			return err
240		}
241		return nil
242	}
243	
244	// jsonValueType 按字段实际写出 JSON 的首字节归类其 JSON 类型。
245	// RawMessage 是从合法 JSON 文档中取出的单个值，首字节足以区分
246	// 字符串/布尔/null/数字/数组/对象，无需再次解码。
247	func jsonValueType(raw json.RawMessage) string {
248		for _, c := range raw {
249			switch c {
250			case ' ', '\t', '\n', '\r':
251				continue
252			case '"':
253				return "string"
254			case 't', 'f':
255				return "boolean"
256			case 'n':
257				return "null"
258			case '[':
259				return "array"
260			case '{':
261				return "object"
262			default:
263				return "number"
264			}
265		}
266		return "invalid json"
267	}
268	
269	// isInt64Number 判断原始 JSON 是否为落在有符号 64 位整数范围内的整数字面量：
270	// 必须是 JSON 数字（首字节为数字或 '-'），且能被 ParseInt 以 10 进制精确解析。
271	// 小数、指数、超界整数均返回 false。
272	func isInt64Number(raw json.RawMessage) bool {
273		if jsonValueType(raw) != "number" {
274			return false
275		}
276		_, err := strconv.ParseInt(strings.TrimSpace(string(raw)), 10, 64)
277		return err == nil
278	}
279	
280	type storedTally struct {
281		ForWeight     int64 `json:"for_weight"`
282		AgainstWeight int64 `json:"against_weight"`
283		TalliedAt     int64 `json:"tallied_at"`
284	}
285	
286	// storedVoteProposal 按成员提交顺序保存成员与委托（顺序不影响相等性），
287	// 动作文本与顺序原样保存（顺序影响相等性）。
288	type storedVoteProposal struct {
289		ID          string             `json:"id"`
290		State       string             `json:"state"`
291		Members     []storedMember     `json:"members"`
292		Delegations []storedDelegation `json:"delegations"`
293		Quorum      int64              `json:"quorum"`
294		StartAt     int64              `json:"start_at"`
295		Deadline    int64              `json:"deadline"`
296		TimelockEnd int64              `json:"timelock_end"`
297		Actions     []string           `json:"actions"`
298		Ballots     []storedBallot     `json:"ballots"`
299		Tally       *storedTally       `json:"tally,omitempty"`
300	}
301	
302	// ---- 校验与派生 ----
303	
304	type proposalSpec struct {
305		members  []VoteMember
306		weights  map[string]int64
307		delegate map[string]string // 直接委托对象
308		pathOf   map[string][]string
309		headOf   map[string]string // 最终代表
310		groupW   map[string]int64  // 最终代表名下归集的全部原始权重
311		total    int64
312	}
313	
314	// validateProposalInput 校验全部创建规则并派生委托路径与代表权重。
315	// 任何非法条件都返回错误，调用方必须整项拒绝。
316	func validateProposalInput(in *CreateVoteInput) (*proposalSpec, error) {
317		if in.ID == "" {
318			return nil, invalidProposal("proposal id must not be empty")
319		}
320		if len(in.Members) == 0 {
321			return nil, invalidProposal("proposal %s: member list must not be empty", in.ID)
322		}
323		weights := make(map[string]int64, len(in.Members))
324		order := make([]string, 0, len(in.Members))
325		for _, m := range in.Members {
326			if m.ID == "" {
327				return nil, invalidProposal("proposal %s: member id must not be empty", in.ID)
328			}
329			if _, dup := weights[m.ID]; dup {
330				return nil, invalidProposal("proposal %s: duplicate member %q", in.ID, m.ID)
331			}
332			if m.Weight <= 0 {
333				return nil, invalidProposal("proposal %s: member %q weight must be a positive integer, got %d", in.ID, m.ID, m.Weight)
334			}
335			weights[m.ID] = m.Weight
336			order = append(order, m.ID)
337		}
338	
339		// 总权重必须在 int64 范围内（各权重已为正）。
340		var total int64
341		for _, m := range in.Members {
342			sum, ok := addInt64(total, m.Weight)
343			if !ok {
344				return nil, invalidProposal("proposal %s: total member weight overflows int64", in.ID)
345			}
346			total = sum
347		}
348	
349		if in.Quorum < 1 || in.Quorum > total {
350			return nil, invalidProposal("proposal %s: quorum must be between 1 and total weight %d, got %d", in.ID, total, in.Quorum)
351		}
352		if !(0 <= in.StartAt && in.StartAt < in.Deadline && in.Deadline <= in.TimelockEnd) {
353			return nil, invalidProposal("proposal %s: times must satisfy 0 <= start < deadline <= timelock, got start=%d deadline=%d timelock=%d",
354				in.ID, in.StartAt, in.Deadline, in.TimelockEnd)
355		}
356	
357		delegate := make(map[string]string, len(in.Delegations))
358		for _, d := range in.Delegations {
359			if d.From == "" || d.To == "" {
360				return nil, invalidProposal("proposal %s: delegation members must not be empty", in.ID)
361			}
362			if _, ok := weights[d.From]; !ok {
363				return nil, invalidProposal("proposal %s: delegation from unknown member %q", in.ID, d.From)
364			}
365			if _, ok := weights[d.To]; !ok {
366				return nil, invalidProposal("proposal %s: delegation to unknown member %q", in.ID, d.To)
367			}
368			if d.From == d.To {
369				return nil, invalidProposal("proposal %s: member %q must not delegate to itself", in.ID, d.From)
370			}
371			if _, dup := delegate[d.From]; dup {
372				return nil, invalidProposal("proposal %s: member %q delegates more than once", in.ID, d.From)
373			}
374			delegate[d.From] = d.To
375		}
376	
377		// 解析每名成员的委托路径：从本人出发，沿直接委托对象逐次前行，
378		// 直到未再委托的最终代表。每个成员出度至多 1，且自委托/循环已被拦截，
379		// 所以该遍历必然终止。
380		// 命中已解析成员时必须拼接其“完整路径”（去掉与之重复的衔接点），
381		// 不能直接跳到它的最终代表，否则多跳链上的中间委托对象会丢失。
382		// 结果只依赖委托关系本身，与成员及委托参数的提交顺序无关。
383		pathOf := make(map[string][]string, len(weights))
384		headOf := make(map[string]string, len(weights))
385		for _, id := range order {
386			if _, done := headOf[id]; done {
387				continue
388			}
389			chain := []string{id}
390			onChain := map[string]int{id: 0}
391			cur := id
392			for {
393				next, has := delegate[cur]
394				if !has {
395					break // cur 即未再委托的最终代表
396				}
397				if pos, cyc := onChain[next]; cyc {
398					return nil, invalidProposal("proposal %s: delegation cycle involving %q", in.ID, chain[pos])
399				}
400				if resolved, ok := pathOf[next]; ok {
401					// 拼接已解析的完整后缀；resolved[0] == next，逐跳衔接且无重复成员。
402					chain = append(chain, resolved...)
403					cur = resolved[len(resolved)-1]
404					break
405				}
406				chain = append(chain, next)
407				onChain[next] = len(chain) - 1
408				cur = next
409			}
410			head := cur
411			// 链上每个成员的路径都是自身到 head 的后缀。命中已解析后缀时，
412			// 后缀成员均已登记，这里只补齐尚未解析的成员。
413			for i := 0; i < len(chain); i++ {
414				member := chain[i]
415				if _, ok := headOf[member]; !ok {
416					pathOf[member] = append([]string(nil), chain[i:]...)
417					headOf[member] = head
418				}
419			}
420		}
421	
422		// 归集每个最终代表名下的全部原始权重；子集和必然不超过总权重。
423		groupW := make(map[string]int64)
424		for _, id := range order {
425			head := headOf[id]
426			sum, ok := addInt64(groupW[head], weights[id])
427			if !ok {
428				return nil, invalidProposal("proposal %s: delegated weight for %q overflows int64", in.ID, head)
429			}
430			groupW[head] = sum
431		}
432	
433		return &proposalSpec{
434			members:  append([]VoteMember(nil), in.Members...),
435			weights:  weights,
436			delegate: delegate,
437			pathOf:   pathOf,
438			headOf:   headOf,
439			groupW:   groupW,
440			total:    total,
441		}, nil
442	}
443	
444	func invalidProposal(format string, args ...any) error {
445		return fmt.Errorf("%w: %s", ErrInvalidProposal, fmt.Sprintf(format, args...))
446	}
447	
448	// proposalsEqual 判断重试内容是否与已存提案逐项相同。
449	// 成员与委托的输入次序不影响比较；动作文本与顺序必须一致。
450	func proposalsEqual(stored *storedVoteProposal, in *CreateVoteInput, spec *proposalSpec) bool {
451		if stored.Quorum != in.Quorum || stored.StartAt != in.StartAt ||
452			stored.Deadline != in.Deadline || stored.TimelockEnd != in.TimelockEnd {
453			return false
454		}
455		if !sameActions(stored.Actions, in.Actions) {
456			return false
457		}
458		if len(stored.Members) != len(in.Members) {
459			return false
460		}
461		for _, m := range stored.Members {
462			if w, ok := spec.weights[m.ID]; !ok || w != m.Weight {
463				return false
464			}
465		}
466		if len(stored.Delegations) != len(in.Delegations) {
467			return false
468		}
469		for _, d := range stored.Delegations {
470			to, ok := spec.delegate[d.From]
471			if !ok || to != d.To {
472				return false
473			}
474		}
475		return true
476	}
477	
478	// ---- 存储操作 ----
479	
480	// CreateVoteProposal 创建一项投票提案。
481	// 同编号且全部内容相同的重试返回已存在提案（existed=true）且不改变任何状态；
482	// 同编号内容不同（或编号已被 register 来源占用）返回 ErrProposalConflict。
483	// 非法条件整项拒绝，不落盘任何部分变化。
484	func (s *Store) CreateVoteProposal(in *CreateVoteInput) (view *VoteProposalView, existed bool, err error) {
485		spec, err := validateProposalInput(in)
486		if err != nil {
487			return nil, false, err
488		}
489		commit, err := s.begin()
490		if err != nil {
491			return nil, false, err
492		}
493		defer commit()
494	
495		state, err := s.loadLocked()
496		if err != nil {
497			return nil, false, err
498		}
499		if existing, ok := state.VoteProposals[in.ID]; ok {
500			if !proposalsEqual(existing, in, spec) {
501				return nil, false, fmt.Errorf("%w: voting proposal %s", ErrProposalConflict, in.ID)
502			}
503			v := voteProposalView(existing)
504			return v, true, nil
505		}
506		if _, ok := state.Proposals[in.ID]; ok {
507			// register 不能覆盖投票提案；反向同样拒绝，两种来源共用编号。
508			return nil, false, fmt.Errorf("%w: proposal id %s already registered", ErrProposalConflict, in.ID)
509		}
510	
511		stored := &storedVoteProposal{
512			ID:          in.ID,
513			State:       "voting",
514			Members:     make([]storedMember, 0, len(in.Members)),
515			Delegations: make([]storedDelegation, 0, len(in.Delegations)),
516			Quorum:      in.Quorum,
517			StartAt:     in.StartAt,
518			Deadline:    in.Deadline,
519			TimelockEnd: in.TimelockEnd,
520			Actions:     copyActions(in.Actions),
521			Ballots:     []storedBallot{},
522		}
523		for _, m := range in.Members {
524			stored.Members = append(stored.Members, storedMember{ID: m.ID, Weight: m.Weight})
525		}
526		for _, d := range in.Delegations {
527			stored.Delegations = append(stored.Delegations, storedDelegation{From: d.From, To: d.To})
528		}
529		state.VoteProposals[in.ID] = stored
530		if err := s.commitLocked(state); err != nil {
531			return nil, false, err
532		}
533		return voteProposalView(stored), false, nil
534	}
535	
536	func voteReject(reason string) error {
537		return fmt.Errorf("%w: %s", ErrVoteRejected, reason)
538	}
539	
540	func tallyReject(reason string) error {
541		return fmt.Errorf("%w: %s", ErrTallyRejected, reason)
542	}
543	
544	// ---- 计票规则（唯一实现，首次计票、打开校验、查询结论共用） ----
545	
546	// ballotCounts 是按逐票明细汇总出的两侧权重。参与量只统计最终代表
547	// 实际投出的票，未投成员的权重既不在 For 也不在 Against 中，
548	// 因而不会被计入 Turnout，更不能直接拿成员总权重充当参与量。
549	type ballotCounts struct {
550		forWeight     int64
551		againstWeight int64
552	}
553	
554	// turnout 返回参与权重（赞成与反对之和），ok 表示合计未溢出 int64。
555	// 两侧各自不超过合法成员总权重时合计必不溢出；此处仍显式检查，
556	// 使“总权重恰好为 math.MaxInt64”的合法提案也不依赖该前提。
557	func (c ballotCounts) turnout() (int64, bool) {
558		return addInt64(c.forWeight, c.againstWeight)
559	}
560	
561	// votePasses 是唯一的通过条件：参与权重达到法定人数（恰好达到也算）
562	// 且赞成严格多于反对。平票、无人投票或参与不足一律不通过。
563	// 通过比较法定人数剩余容量判断参与量，避免 for+against 上溢时回绕为负，
564	// 把已达标（乃至总权重恰好为 int64 上限）的提案误判为参与不足。
565	func votePasses(forWeight, againstWeight, quorum int64) bool {
566		if forWeight <= againstWeight {
567			return false // 平票或赞成更少都不通过；两侧非负，无票时同样落在这里
568		}
569		return forWeight >= quorum-againstWeight // 等价于 for+against >= quorum，且不做上溢加法
570	}
571	
572	// tallyVerdict 把通过条件映射为提案首次计票后的状态。
573	func tallyVerdict(passed bool) string {
574		if passed {
575			return "passed"
576		}
577		return "rejected"
578	}
579	
580	// countBallots 只按票据选择累加两侧权重，不做代表资格与票重核对
581	// （资格核对由 verifyBallots 负责）。任何一侧溢出 int64 都返回损坏错误。
582	func countBallots(ballots []storedBallot) (ballotCounts, error) {
583		var c ballotCounts
584		for _, b := range ballots {
585			if b.Support {
586				sum, ok := addInt64(c.forWeight, b.Weight)
587				if !ok {
588					return ballotCounts{}, errors.New("for-side ballot weights overflow int64")
589				}
590				c.forWeight = sum
591			} else {
592				sum, ok := addInt64(c.againstWeight, b.Weight)
593				if !ok {
594					return ballotCounts{}, errors.New("against-side ballot weights overflow int64")
595				}
596				c.againstWeight = sum
597			}
598		}
599		return c, nil
600	}
601	
602	// verifyBallots 依据成员名单与委托关系逐票核对并汇总：
603	// 代表必须是最终代表、不得重复、票重必须等于委托后归集到其名下的权重。
604	// 这些条件全部由打开状态文件时的严格校验保证，首次计票路径再核对一次，
605	// 使两条路径对“票重/代表是否可信”的判定使用同一份规则。
606	// 汇总只含实际投出的票；任一条件不符返回带具体原因的错误，
607	// 错误分类（ErrStateCorrupt）由调用方按自身路径统一包装。
608	func verifyBallots(id string, ballots []storedBallot, spec *proposalSpec) (ballotCounts, error) {
609		seen := map[string]bool{}
610		for i, b := range ballots {
611			if b.Representative == "" {
612				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d has empty representative", id, i)
613			}
614			if spec.headOf[b.Representative] != b.Representative {
615				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d: %q is not a final representative",
616					id, i, b.Representative)
617			}
618			if seen[b.Representative] {
619				return ballotCounts{}, fmt.Errorf("proposal %s has duplicate stored ballot for %q", id, b.Representative)
620			}
621			seen[b.Representative] = true
622			if b.Weight != spec.groupW[b.Representative] {
623				return ballotCounts{}, fmt.Errorf("proposal %s ballot weight for %q (%d) does not match roster delegation (%d)",
624					id, b.Representative, b.Weight, spec.groupW[b.Representative])
625			}
626		}
627		counts, err := countBallots(ballots)
628		if err != nil {
629			return ballotCounts{}, fmt.Errorf("proposal %s %v", id, err)
630		}
631		return counts, nil
632	}
633	
634	// CastVote 在一项投票提案上投票。调用方通过 now 提供当前时间。
635	// 只有最终代表本人可投赞成/反对票，每位代表一张票，票重为归集到其名下的
636	// 全部原始权重。相同选择的重试始终返回首次记录；改投报冲突。
637	// 首次投票只接受 start <= now < deadline；计票之后拒绝一切新票。
638	func (s *Store) CastVote(id, voter string, support bool, now int64) (*BallotView, error) {
639		if voter == "" {
640			return nil, voteReject("voter id must not be empty")
641		}
642		commit, err := s.begin()
643		if err != nil {
644			return nil, err
645		}
646		defer commit()
647	
648		state, err := s.loadLocked()
649		if err != nil {
650			return nil, err
651		}
652		p, ok := state.VoteProposals[id]
653		if !ok {
654			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
655		}
656		spec, verr := specOf(p)
657		if verr != nil {
658			return nil, verr // 正常路径不会发生：打开与提交前均已严格校验
659		}
660		if _, member := spec.weights[voter]; !member {
661			return nil, voteReject(fmt.Sprintf("voter %q is not on the member roster of %s", voter, id))
662		}
663		if spec.headOf[voter] != voter {
664			return nil, voteReject(fmt.Sprintf("voter %q has delegated the vote to %q and may not vote directly", voter, spec.headOf[voter]))
665		}
666		// 已投过票：相同选择的重试始终返回首次记录（与时间窗口、是否已计票无关）；
667		// 改投另一选择报冲突，绝不静默覆盖。
668		for i := range p.Ballots {
669			if p.Ballots[i].Representative == voter {
670				if p.Ballots[i].Support != support {
671					return nil, fmt.Errorf("%w: representative %q already voted %s for %s; changing the vote is not allowed",
672						ErrProposalConflict, voter, voteChoice(p.Ballots[i].Support), id)
673				}
674				b := p.Ballots[i]
675				return &BallotView{Representative: b.Representative, Weight: b.Weight, Support: b.Support, VotedAt: b.VotedAt}, nil
676			}
677		}
678		if p.Tally != nil {
679			return nil, voteReject(fmt.Sprintf("proposal %s has already been tallied; voting is closed", id))
680		}
681		if now < p.StartAt || now >= p.Deadline {
682			return nil, voteReject(fmt.Sprintf("proposal %s is not open for voting at now=%d (start=%d deadline=%d)", id, now, p.StartAt, p.Deadline))
683		}
684	
685		p.Ballots = append(p.Ballots, mustStoreBallot(voter, spec.groupW[voter], support, now))
686		if err := s.commitLocked(state); err != nil {
687			return nil, err
688		}
689		return &BallotView{Representative: voter, Weight: spec.groupW[voter], Support: support, VotedAt: now}, nil
690	}
691	
692	func voteChoice(support bool) string {
693		if support {
694			return "for"
695		}
696		return "against"
697	}
698	
699	// TallyVote 在截止时刻或之后进行首次计票：赞成与反对权重之和达到法定人数，
700	// 且赞成严格多于反对才通过。未投权重不计入参与量。
701	// 计票只确定状态，不转账；再次计票始终返回首次结论。
702	func (s *Store) TallyVote(id string, now int64) (*TallyResultView, error) {
703		commit, err := s.begin()
704		if err != nil {
705			return nil, err
706		}
707		defer commit()
708	
709		state, err := s.loadLocked()
710		if err != nil {
711			return nil, err
712		}
713		p, ok := state.VoteProposals[id]
714		if !ok {
715			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
716		}
717		if p.Tally != nil {
718			return storedTallyResult(p), nil
719		}
720		if now < p.Deadline {
721			return nil, tallyReject(fmt.Sprintf("voting for %s is still open: now=%d deadline=%d", id, now, p.Deadline))
722		}
723	
724		spec, verr := specOf(p)
725		if verr != nil {
726			return nil, verr
727		}
728		// 计票规则只有一份：同一套“代表资格 + 票重 + 两侧汇总 + 法定人数/多数”
729		// 同时用于首次计票、打开文件时的重放校验与查询结论。
730		counts, verr := verifyBallots(id, p.Ballots, spec)
731		if verr != nil {
732			return nil, fmt.Errorf("%w: %v", ErrStateCorrupt, verr)
733		}
734		passed := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
735		p.Tally = &storedTally{ForWeight: counts.forWeight, AgainstWeight: counts.againstWeight, TalliedAt: now}
736		p.State = tallyVerdict(passed)
737		if err := s.commitLocked(state); err != nil {
738			return nil, err
739		}
740		return storedTallyResult(p), nil
741	}
742	
743	// storedTallyResult 从已存储提案重建首次计票结论；尚未计票时返回 nil。
744	// Passed 由唯一的通过规则（votePasses）按保存权重重算：提案后续执行
745	// （executed）不改变首次结论，查询结论与首次计票结论因此始终一致。
746	// 调用方持有的状态均经过 validateState，两侧合计必然不超过合法总权重。
747	func storedTallyResult(p *storedVoteProposal) *TallyResultView {
748		if p.Tally == nil {
749			return nil
750		}
751		c := ballotCounts{forWeight: p.Tally.ForWeight, againstWeight: p.Tally.AgainstWeight}
752		turnout, _ := c.turnout()
753		return &TallyResultView{
754			ForWeight:     c.forWeight,
755			AgainstWeight: c.againstWeight,
756			Turnout:       turnout,
757			Quorum:        p.Quorum,
758			Passed:        votePasses(c.forWeight, c.againstWeight, p.Quorum),
759			TalliedAt:     p.Tally.TalliedAt,
760		}
761	}
762	
763	// VoteProposal 按编号查询一项投票提案；不存在时 ok 为 false。
764	func (s *Store) VoteProposal(id string) (*VoteProposalView, bool, error) {
765		state, err := s.readState()
766		if err != nil {
767			return nil, false, err
768		}
769		p, ok := state.VoteProposals[id]
770		if !ok {
771			return nil, false, nil
772		}
773		return voteProposalView(p), true, nil
774	}
775	
776	// VoteProposals 返回全部投票提案，按编号排序。
777	func (s *Store) VoteProposals() ([]*VoteProposalView, error) {
778		state, err := s.readState()
779		if err != nil {
780			return nil, err
781		}
782		return voteProposalViews(state), nil
783	}
784	
785	func voteProposalViews(state *storedState) []*VoteProposalView {
786		out := make([]*VoteProposalView, 0, len(state.VoteProposals))
787		for _, p := range state.VoteProposals {
788			out = append(out, voteProposalView(p))
789		}
790		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
791		return out
792	}
793	
794	func voteProposalView(p *storedVoteProposal) *VoteProposalView {
795		spec, err := specOf(p)
796		if err != nil {
797			// 调用方持有的状态均经过 validateState；损坏文件根本无法打开。
798			panic("govflow: building view of corrupt proposal: " + err.Error())
799		}
800		members := make([]MemberView, 0, len(p.Members))
801		for _, m := range p.Members { // 保持成员提交顺序
802			mv := MemberView{
803				ID:       m.ID,
804				Weight:   m.Weight,
805				Path:     append([]string(nil), spec.pathOf[m.ID]...),
806				Delegate: spec.headOf[m.ID],
807			}
808			if to, ok := spec.delegate[m.ID]; ok {
809				mv.Direct = to
810			}
811			members = append(members, mv)
812		}
813		ballots := make([]BallotView, 0, len(p.Ballots))
814		for _, b := range p.Ballots { // 保持首次投票先后顺序
815			ballots = append(ballots, BallotView{
816				Representative: b.Representative,
817				Weight:         b.Weight,
818				Support:        b.Support,
819				VotedAt:        b.VotedAt,
820			})
821		}
822		v := &VoteProposalView{
823			ID:          p.ID,
824			Source:      "vote",
825			State:       p.State,
826			Quorum:      p.Quorum,
827			StartAt:     p.StartAt,
828			Deadline:    p.Deadline,
829			TimelockEnd: p.TimelockEnd,
830			Actions:     copyActions(p.Actions),
831			TotalWeight: spec.total,
832			Members:     members,
833			Ballots:     ballots,
834		}
835		if p.Tally != nil {
836			v.Tally = storedTallyResult(p)
837		}
838		return v
839	}
840	
841	// specOf 从已存储提案重建校验派生物（委托路径、代表归集权重）。
842	func specOf(p *storedVoteProposal) (*proposalSpec, error) {
843		in := &CreateVoteInput{
844			ID:          p.ID,
845			Quorum:      p.Quorum,
846			StartAt:     p.StartAt,
847			Deadline:    p.Deadline,
848			TimelockEnd: p.TimelockEnd,
849			Actions:     p.Actions,
850		}
851		in.Members = make([]VoteMember, len(p.Members))
852		for i, m := range p.Members {
853			in.Members[i] = VoteMember{ID: m.ID, Weight: m.Weight}
854		}
855		in.Delegations = make([]Delegation, len(p.Delegations))
856		for i, d := range p.Delegations {
857			in.Delegations[i] = Delegation{From: d.From, To: d.To}
858		}
859		return validateProposalInput(in)
860	}
861	
862	// validateVoteProposals 在打开状态文件时严格校验全部投票提案：
863	// 编号与 register 来源不冲突；状态机与计票结论一致；票重/代表与名单及委托明细一致；
864	// 首次投票时间落在窗口内；首次计票不早于截止且结论可由明细重放。
865	func validateVoteProposals(state *storedState) error {
866		for key, p := range state.VoteProposals {
867			if p == nil {
868				return fmt.Errorf("voting proposal %q is empty", key)
869			}
870			if p.ID != key || p.ID == "" {
871				return fmt.Errorf("voting proposal key %q does not match id %q", key, p.ID)
872			}
873			if _, collide := state.Proposals[p.ID]; collide {
874				return fmt.Errorf("proposal id %q exists in both proposal sources", p.ID)
875			}
876			switch p.State {
877			case "voting", "passed", "rejected", "executed":
878			default:
879				return fmt.Errorf("voting proposal %q has unknown state %q", p.ID, p.State)
880			}
881			spec, err := specOf(p)
882			if err != nil {
883				return err
884			}
885	
886			// 每张已保存票据都必须明确写出 representative/weight/support/voted_at
887			// 且非 null、JSON 类型正确。先于代表资格与票重核对执行：字段缺损时直接判
888			// 整份文件损坏，绝不能把缺失的 support 默认成反对票、把缺失的 voted_at
889			// 默认成 0 后再继续给出查询或计票的部分结果。
890			for i := range p.Ballots {
891				if err := validateStoredBallot(p.ID, i, &p.Ballots[i]); err != nil {
892					return err
893				}
894			}
895	
896			// 票据明细的代表资格、重复票据、票重与两侧汇总，全部复用首次计票的
897			// verifyBallots：打开重放与首次计票对“票重/代表是否可信”只有一份判定，
898			// 汇总只含最终代表实际投出的票，未投成员权重不进入参与量。
899			counts, err := verifyBallots(p.ID, p.Ballots, spec)
900			if err != nil {
901				return err
902			}
903			// 首次投票时间必须落在窗口 [start, deadline) 内；此约束与票重汇总无关，
904			// 仍只属于打开时的明细校验。
905			for _, b := range p.Ballots {
906				if b.VotedAt < p.StartAt || b.VotedAt >= p.Deadline {
907					return fmt.Errorf("voting proposal %q ballot by %q cast at %d outside window [%d,%d)",
908						p.ID, b.Representative, b.VotedAt, p.StartAt, p.Deadline)
909				}
910			}
911	
912			switch {
913			case p.Tally == nil:
914				if p.State != "voting" {
915					return fmt.Errorf("voting proposal %q is %s but has no tally", p.ID, p.State)
916				}
917			default:
918				if p.State == "voting" {
919					return fmt.Errorf("voting proposal %q has a tally but is still in voting state", p.ID)
920				}
921				if p.Tally.TalliedAt < p.Deadline {
922					return fmt.Errorf("voting proposal %q tallied at %d before deadline %d", p.ID, p.Tally.TalliedAt, p.Deadline)
923				}
924				if p.Tally.ForWeight != counts.forWeight || p.Tally.AgainstWeight != counts.againstWeight {
925					return fmt.Errorf("voting proposal %q tally weights for=%d/against=%d do not replay ballots for=%d/against=%d",
926						p.ID, p.Tally.ForWeight, p.Tally.AgainstWeight, counts.forWeight, counts.againstWeight)
927				}
928				// 通过条件同样只有一份：保存状态必须与票据重放出的结论一致，
929				// executed 是 passed 提案执行后的后继状态，仍对应“首次通过”。
930				passedNow := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
931				if passedNow != (p.State == "passed" || p.State == "executed") {
932					return fmt.Errorf("voting proposal %q state %s does not match quorum/majority replay", p.ID, p.State)
933				}
934			}
935		}
936		return nil
937	}
938

