34	const (
35		stateMagic   = "govflow-treasury-state"
36		stateVersion = 1
37		lockSuffix   = ".lock"
38	)
39	
40	// BalanceUpdate 记录一个账户在一次动作前后的余额。
41	type BalanceUpdate struct {
42		Account string `json:"account"`
43		Before  int64  `json:"before"`
44		After   int64  `json:"after"`
45	}
46	
47	// ActionReceipt 是凭据中对单项动作的留痕：动作原文、在提案中的顺序编号（0 起），
48	// 以及该动作引发的资金库与收款账户余额变动。
49	type ActionReceipt struct {
50		Index     int           `json:"index"`
51		Action    string        `json:"action"`
52		Treasury  BalanceUpdate `json:"treasury"`
53		Recipient BalanceUpdate `json:"recipient"`
54	}
55	
56	// Receipt 是一项提案首次成功执行后生成的执行凭据。
57	// 一项提案只允许成功一次；重试返回同一份凭据。
58	//
59	// executed_at 必须明确写出且不得早于对应提案的 timelock_end：首次执行只在
60	// now 达到时间锁后发生，保存的凭据必须满足同一条执行资格规则。字段缺失、
61	// 为 null 或类型不符都不得被折叠成 0 再当作合法凭据读出，因此解码时保留
62	// 字段的原始 JSON，由 validateState 区分“缺失/空值/类型不符/早于时间锁”。
63	type Receipt struct {
64		ProposalID string          `json:"proposal_id"`
65		ExecutedAt int64           `json:"executed_at"` // 首次成功执行时调用方提供的时间
66		Order      int             `json:"order"`       // 成功提交的先后顺序，0 起
67		Actions    []ActionReceipt `json:"actions"`
68	
69		executedAtRaw json.RawMessage
70	}
71	
72	// receiptJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
73	type receiptJSONShape struct {
74		ProposalID string          `json:"proposal_id"`
75		ExecutedAt json.RawMessage `json:"executed_at"`
76		Order      int             `json:"order"`
77		Actions    []ActionReceipt `json:"actions"`
78	}
79	
80	// UnmarshalJSON 保留 executed_at 是否出现及其原始写法（缺失为 nil、null 为
81	// "null"），使“字段缺失”与“显式写出 0”在解码后仍可区分：encoding/json 直接
82	// 解进 int64 会把缺失/null/类型不符都折叠成 0。判定统一交给 validateState，
83	// 此处只在字段确实是 int64 整数时填充 ExecutedAt。
84	func (r *Receipt) UnmarshalJSON(data []byte) error {
85		var shape receiptJSONShape
86		if err := json.Unmarshal(data, &shape); err != nil {
87			return err
88		}
89		r.ProposalID = shape.ProposalID
90		r.Order = shape.Order
91		r.Actions = shape.Actions
92		r.executedAtRaw = shape.ExecutedAt
93		if isInt64Number(shape.ExecutedAt) {
94			_ = json.Unmarshal(shape.ExecutedAt, &r.ExecutedAt)
95		}
96		return nil
97	}
98	
99	// ProposalRecord 是已登记提案的对外视图。State 只可能是 passed 或 executed。
100	type ProposalRecord struct {
101		ID          string   `json:"id"`
102		State       string   `json:"state"`
103		TimelockEnd int64    `json:"timelock_end"`
104		Actions     []string `json:"actions"`
105	}
106	
107	// ---- 磁盘结构（JSON） ----
108	
109	type storedProposal struct {
110		ID          string   `json:"id"`
111		State       string   `json:"state"`
112		TimelockEnd int64    `json:"timelock_end"`
113		Actions     []string `json:"actions"`
114	}
115	
116	type storedState struct {
117		Magic           string                         `json:"magic"`
118		Version         int                            `json:"version"`
119		InitialTreasury int64                          `json:"initial_treasury"`
120		Treasury        int64                          `json:"treasury"`
121		Balances        map[string]int64               `json:"balances"`
122		Proposals       map[string]*storedProposal     `json:"proposals"`
123		Receipts        []*Receipt                     `json:"receipts"`
124		VoteProposals   map[string]*storedVoteProposal `json:"vote_proposals"`
125	}
126	
127	// Store 是绑定到单个本地状态文件的资金库句柄。
128	// 多个 goroutine 可并发使用同一个 Store；不同 Store/进程操作同一状态文件时，
129	// 通过进程内互斥锁与文件锁（flock）串行化。
130	type Store struct {
131		path   string
132		mu     sync.Mutex // 保护本句柄上的全部操作
133		lockFD *os.File   // 跨进程文件锁
134		closed bool
135	}
136	
137	// 进程内按规范路径共享的互斥锁，保证同进程内多个 Store 句柄也互相串行。
138	var (
139		pathLocksMu sync.Mutex
140		pathLocks   = map[string]*sync.Mutex{}
141	)
142	
143	// canonicalPath 将路径规范化为绝对路径，保证不同拼写（如 t.json 与 ./t.json）
144	// 命中同一把进程内锁与同一个锁文件。有意不解析符号链接：文件在初始化前后必须
145	// 解析到同一个键，硬链接/绑定挂载等更深层别名不在本地单文件场景的处理范围内。
146	func canonicalPath(path string) (string, error) {
147		return filepath.Abs(path)
148	}
149	
150	func inProcessLock(path string) *sync.Mutex {
151		pathLocksMu.Lock()
152		defer pathLocksMu.Unlock()
153		m, ok := pathLocks[path]
154		if !ok {
155			m = &sync.Mutex{}
156			pathLocks[path] = m
157		}
158		return m
159	}
160	
161	// InitTreasury 创建一个全新的状态文件并写入初始资金库余额。
162	// 只有新文件才能初始化：路径已存在（含损坏文件）一律拒绝，不会重置或覆盖。
163	// treasury 必须落在有符号 64 位整数范围内且不得为负。
164	func InitTreasury(path string, treasury int64) (*Store, error) {
165		if treasury < 0 {
166			return nil, fmt.Errorf("%w: initial treasury balance must not be negative", ErrInvalidRegistration)
167		}
168		path, err := canonicalPath(path)
169		if err != nil {
170			return nil, err
171		}
172		pathMu := inProcessLock(path)
173		pathMu.Lock()
174		defer pathMu.Unlock()
175	
176		// 先打开/创建锁文件并取跨进程锁，再创建状态文件，消除“空文件已出现、
177		// 尚未写入”期间被其它进程 Open 判为损坏的窗口。
178		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
179		if err != nil {
180			return nil, err
181		}
182		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
183			_ = lockFD.Close()
184			return nil, err
185		}
186		// O_EXCL 保证与并发初始化竞争时只有一方成功。
187		fd, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
188		if err != nil {
189			_ = syscall.Flock(int(lockFD.Fd()), syscall.LOCK_UN)
190			_ = lockFD.Close()
191			if errors.Is(err, fs.ErrExist) {
192				return nil, fmt.Errorf("%w: %s", ErrTreasuryAlreadyInit, path)
193			}
194			return nil, err
195		}
196		_ = fd.Close()
197	
198		store := &Store{path: path, lockFD: lockFD}
199		if err := store.commitLocked(newStoredState(treasury)); err != nil {
200			_ = store.funlock()
201			_ = lockFD.Close()
202			_ = os.Remove(path)
203			return nil, err
204		}
205		// 初始化完成后立即释放跨进程锁；后续每次操作各自短持锁。
206		if err := store.funlock(); err != nil {
207			_ = lockFD.Close()
208			_ = os.Remove(path)
209			return nil, err
210		}
211		return store, nil
212	}
213	
214	// Open 打开已有的资金库状态文件。文件损坏时明确拒绝，不会重建或覆盖原文件。
215	func Open(path string) (*Store, error) {
216		path, err := canonicalPath(path)
217		if err != nil {
218			return nil, err
219		}
220		pathMu := inProcessLock(path)
221		pathMu.Lock()
222		defer pathMu.Unlock()
223		return openStoreHoldingPathLock(path)
224	}
225	
226	// openStoreHoldingPathLock 的调用方必须持有该路径的进程内互斥锁。
227	func openStoreHoldingPathLock(path string) (*Store, error) {
228		if _, err := os.Stat(path); err != nil {
229			return nil, err
230		}
231		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
232		if err != nil {
233			return nil, err
234		}
235		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
236			_ = lockFD.Close()
237			return nil, err
238		}
239		store := &Store{path: path, lockFD: lockFD}
240		if _, err := store.loadLocked(); err != nil {
241			_ = store.funlock()
242			_ = lockFD.Close()
243			return nil, err
244		}
245		// 打开时已做严格校验；锁随即释放，每次操作再各自短持锁。
246		if err := store.funlock(); err != nil {
247			_ = lockFD.Close()
248			return nil, err
249		}
250		return store, nil
251	}
252	
253	// Path 返回状态文件路径。
254	func (s *Store) Path() string { return s.path }
255	
256	// Close 释放文件锁。关闭后其它操作返回错误。
257	func (s *Store) Close() error {
258		s.mu.Lock()
259		defer s.mu.Unlock()
260		if s.closed {
261			return nil
262		}
263		s.closed = true
264		if err := s.funlock(); err != nil {
265			_ = s.lockFD.Close()
266			return err
267		}
268		return s.lockFD.Close()
269	}
270	
271	func (s *Store) flock(how int) error {
272		if s.lockFD == nil {
273			return errors.New("treasury store is closed")
274		}
275		return syscall.Flock(int(s.lockFD.Fd()), how)
276	}
277	
278	func (s *Store) funlock() error {
279		if s.lockFD == nil {
280			return nil
281		}
282		return syscall.Flock(int(s.lockFD.Fd()), syscall.LOCK_UN)
283	}
284	
285	// begin 串行化一次读改写操作：先取进程内路径锁，再取跨进程排他文件锁。
286	// 返回的 commit 在操作结束时释放锁。
287	func (s *Store) begin() (func(), error) {
288		pathMu := inProcessLock(s.path)
289		pathMu.Lock()
290		s.mu.Lock()
291		if s.closed {
292			s.mu.Unlock()
293			pathMu.Unlock()
294			return nil, errors.New("treasury store is closed")
295		}
296		if err := s.flock(syscall.LOCK_EX); err != nil {
297			s.mu.Unlock()
298			pathMu.Unlock()
299			return nil, err
300		}
301		return func() {
302			_ = s.funlock()
303			s.mu.Unlock()
304			pathMu.Unlock()
305		}, nil
306	}
307	
308	func newStoredState(treasury int64) *storedState {
309		return &storedState{
310			Magic:           stateMagic,
311			Version:         stateVersion,
312			InitialTreasury: treasury,
313			Treasury:        treasury,
314			Balances:        map[string]int64{},
315			Proposals:       map[string]*storedProposal{},
316			Receipts:        []*Receipt{},
317			VoteProposals:   map[string]*storedVoteProposal{},
318		}
319	}
320	
321	// ---- 登记 ----
322	
323	// Register 登记一项已通过（passed）的提案，保留时间锁与动作原文。
324	// 编号必须非空；动作列表可为空（执行时会因动作为空被拒绝），动作原文不做改写。
325	// 同编号且时间锁、动作原文与首次登记完全相同的重试返回 existed=true；
326	// 内容不同则返回 ErrProposalConflict。
327	func (s *Store) Register(id string, timelockEnd int64, actions []string) (existed bool, err error) {
328		if id == "" {
329			return false, fmt.Errorf("%w: proposal id must not be empty", ErrInvalidRegistration)
330		}
331		commit, err := s.begin()
332		if err != nil {
333			return false, err
334		}
335		defer commit()
336	
337		state, err := s.loadLocked()
338		if err != nil {
339			return false, err
340		}
341		stored := copyActions(actions)
342		if existing, ok := state.Proposals[id]; ok {
343			if existing.TimelockEnd == timelockEnd && sameActions(existing.Actions, stored) {
344				return true, nil
345			}
346			return false, fmt.Errorf("%w: proposal %s", ErrProposalConflict, id)
347		}
348		// 两种来源共用编号：register 不能覆盖投票提案或绕过其投票结论。
349		if vp, ok := state.VoteProposals[id]; ok {
350			return false, fmt.Errorf("%w: proposal id %s belongs to a voting proposal (state=%s)", ErrProposalConflict, id, vp.State)
351		}
352		state.Proposals[id] = &storedProposal{
353			ID:          id,
354			State:       "passed",
355			TimelockEnd: timelockEnd,
356			Actions:     stored,
357		}
358		if err := s.commitLocked(state); err != nil {
359			return false, err
360		}
361		return false, nil
362	}
363	
364	func copyActions(actions []string) []string {
365		if actions == nil {
366			return nil
367		}
368		copied := make([]string, len(actions))
369		copy(copied, actions)
370		return copied
371	}
372	
373	// sameActions 将 nil 与空切片视为等价，其余按顺序逐字比较。
374	func sameActions(a, b []string) bool {
375		if len(a) != len(b) {
376			return false
377		}
378		for i := range a {
379			if a[i] != b[i] {
380				return false
381			}
382		}
383		return true
384	}
385	
386	// ---- 执行 ----
387	
388	// executionTarget 是 register 与投票两种来源提案在执行路径上的统一视图。
389	type executionTarget struct {
390		state        string
391		timelockEnd  int64
392		actions      []string
393		markExecuted func()
394	}
395	
396	// resolveExecutable 在两种提案表中按编号定位执行目标；不存在返回 nil。
397	func resolveExecutable(state *storedState, id string) *executionTarget {
398		if p, ok := state.Proposals[id]; ok {
399			return &executionTarget{
400				state:        p.State,
401				timelockEnd:  p.TimelockEnd,
402				actions:      p.Actions,
403				markExecuted: func() { p.State = "executed" },
404			}
405		}
406		if vp, ok := state.VoteProposals[id]; ok {
407			return &executionTarget{
408				state:        vp.State,
409				timelockEnd:  vp.TimelockEnd,
410				actions:      vp.Actions,
411				markExecuted: func() { vp.State = "executed" },
412			}
413		}
414		return nil
415	}
416	
417	// proposalOwners 将两个来源的提案编号映射到状态、时间锁与动作，供凭据重放交叉校验。
418	func proposalOwnerState(state *storedState, id string) (string, int64, []string, bool) {
419		if p, ok := state.Proposals[id]; ok {
420			return p.State, p.TimelockEnd, p.Actions, true
421		}
422		if vp, ok := state.VoteProposals[id]; ok {
423			return vp.State, vp.TimelockEnd, vp.Actions, true
424		}
425		return "", 0, nil, false
426	}
427	
428	// Execute 按编号执行一项提案。调用方通过 now 提供当前时间。
429	// 只有 passed 状态、now 已达到时间锁且动作非空的提案可以首次执行；
430	// 成功后状态变为 executed 并返回凭据。资格不符、动作格式错误、余额不足、
431	// 金额计算溢出都返回明确原因，整项提案不产生部分转账，也不消耗执行机会。
432	// 已完成提案再次执行（即使 now 不同）直接返回首次成功凭据。
433	func (s *Store) Execute(id string, now int64) (*Receipt, error) {
434		commit, err := s.begin()
435		if err != nil {
436			return nil, err
437		}
438		defer commit()
439	
440		state, err := s.loadLocked()
441		if err != nil {
442			return nil, err
443		}
444		target := resolveExecutable(state, id)
445		if target == nil {
446			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
447		}
448		if target.state == "executed" {
449			if rcpt := findReceipt(state.Receipts, id); rcpt != nil {
450				return cloneReceipt(rcpt), nil
451			}
452			return nil, fmt.Errorf("%w: executed proposal %s has no receipt", ErrStateCorrupt, id)
453		}
454		if target.state != "passed" {
455			return nil, execReject(fmt.Sprintf("proposal %s is not passed (state=%s)", id, target.state))
456		}
457		if now < target.timelockEnd {
458			return nil, execReject(fmt.Sprintf("timelock not reached for %s: now=%d timelock_end=%d", id, now, target.timelockEnd))
459		}
460		if len(target.actions) == 0 {
461			return nil, execReject(fmt.Sprintf("proposal %s has no actions", id))
462		}
463	
464		// 第一阶段：在副本上按统一转账规则（planTransfers）校验并预演全部
465		// 动作。任何一步失败都直接返回，副本之外的状态不落盘。
466		steps, simTreasury, simBalances, perr := planTransfers(target.actions, state.Treasury, state.Balances)
467		if perr != nil {
468			return nil, perr
469		}
470	
471		// 第二阶段：全部预演成功后构造凭据并一次性原子提交。
472		receipt := &Receipt{
473			ProposalID: id,
474			ExecutedAt: now,
475			Order:      len(state.Receipts),
476			Actions:    make([]ActionReceipt, 0, len(steps)),
477		}
478		// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
479		// executed_at 判定时不会把本进程新建的凭据误判为字段缺失。
480		receipt.executedAtRaw, _ = json.Marshal(now)
481		for i, st := range steps {
482			receipt.Actions = append(receipt.Actions, st.actionReceipt(i, target.actions[i]))
483		}
484		state.Treasury = simTreasury
485		state.Balances = simBalances
486		target.markExecuted()
487		state.Receipts = append(state.Receipts, receipt)
488	
489		if err := s.commitLocked(state); err != nil {
490			return nil, err
491		}
492		return cloneReceipt(receipt), nil
493	}
494	
495	func findReceipt(receipts []*Receipt, id string) *Receipt {
496		for _, r := range receipts {
497			if r.ProposalID == id {
498				return r
499			}
500		}
501		return nil
502	}
503	
504	func cloneReceipt(r *Receipt) *Receipt {
505		if r == nil {
506			return nil
507		}
508		copied := *r
509		if r.Actions != nil {
510			copied.Actions = make([]ActionReceipt, len(r.Actions))
511			copy(copied.Actions, r.Actions)
512		}
513		return &copied
514	}
