517	
518	// BalanceSnapshot 是同一份完整已提交状态下的资金库余额与全部收款账户余额。
519	// 一次 BalanceSnapshot 调用只读取一次状态文件，保证返回的字段彼此一致：
520	// 不会把不同提交时刻的余额拼在一起。
521	type BalanceSnapshot struct {
522		Treasury int64            `json:"treasury"`
523		Balances map[string]int64 `json:"balances"`
524	}
