526	// BalanceSnapshot 在一次持锁读取中取得资金库与全部收款账户余额。
527	// 返回的 Balances 是副本（永不为 nil），调用方可自由使用；
528	// 后续执行不会改变已返回的快照，下一次调用重新读取当前已提交状态。
529	func (s *Store) BalanceSnapshot() (*BalanceSnapshot, error) {
530		state, err := s.readState()
531		if err != nil {
532			return nil, err
533		}
534		out := &BalanceSnapshot{
535			Treasury: state.Treasury,
536			Balances: make(map[string]int64, len(state.Balances)),
537		}
538		for k, v := range state.Balances {
539			out.Balances[k] = v
540		}
541		return out, nil
542	}
