553	// Balance 返回收款账户余额；从未出现过的账户余额为零。
554	func (s *Store) Balance(account string) (int64, error) {
555		state, err := s.readState()
556		if err != nil {
557			return 0, err
558		}
559		return state.Balances[account], nil
560	}
