562	// Balances 返回全部出现过的收款账户余额的副本，按账户名排序。
563	func (s *Store) Balances() (map[string]int64, error) {
564		state, err := s.readState()
565		if err != nil {
566			return nil, err
567		}
568		out := make(map[string]int64, len(state.Balances))
569		for k, v := range state.Balances {
570			out[k] = v
571		}
572		return out, nil
573	}
