575	// Proposal 按编号返回提案登记信息；不存在时 ok 为 false。
576	func (s *Store) Proposal(id string) (ProposalRecord, bool, error) {
577		state, err := s.readState()
578		if err != nil {
579			return ProposalRecord{}, false, err
580		}
581		p, ok := state.Proposals[id]
582		if !ok {
583			return ProposalRecord{}, false, nil
584		}
585		return toProposalRecord(p), true, nil
586	}
587	
588	// Proposals 返回全部已登记提案，按编号排序。
589	func (s *Store) Proposals() ([]ProposalRecord, error) {
590		state, err := s.readState()
591		if err != nil {
592			return nil, err
593		}
594		return proposalRecords(state), nil
595	}
596	
597	func proposalRecords(state *storedState) []ProposalRecord {
598		out := make([]ProposalRecord, 0, len(state.Proposals))
599		for _, p := range state.Proposals {
600			out = append(out, toProposalRecord(p))
601		}
602		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
603		return out
604	}
605	
606	// ProposalsSnapshot 是同一份完整已提交状态下的登记提案与投票提案列表。
607	// 一次 ProposalsSnapshot 调用只读取一次状态文件，保证两个来源的提案状态、
608	// 动作与投票明细彼此一致：不会把不同提交时刻的提案状态拼在一起。
609	type ProposalsSnapshot struct {
610		Registered []ProposalRecord    `json:"registered"`
611		Voting     []*VoteProposalView `json:"voting"`
612	}
613	
614	// ProposalsSnapshot 在一次持锁读取中取得全部登记提案与全部投票提案。
615	// Registered 按编号排序，Voting 按编号排序；返回的切片与记录均为副本，
616	// 后续执行不会改变已返回的快照，下一次调用重新读取当前已提交状态。
617	func (s *Store) ProposalsSnapshot() (*ProposalsSnapshot, error) {
618		state, err := s.readState()
619		if err != nil {
620			return nil, err
621		}
622		return &ProposalsSnapshot{
623			Registered: proposalRecords(state),
624			Voting:     voteProposalViews(state),
625		}, nil
626	}
627	
628	func toProposalRecord(p *storedProposal) ProposalRecord {
629		return ProposalRecord{
630			ID:          p.ID,
631			State:       p.State,
632			TimelockEnd: p.TimelockEnd,
633			Actions:     copyActions(p.Actions),
634		}
635	}
