637	// Receipt 按编号返回执行凭据；尚未成功执行或不存在时 ok 为 false。
638	func (s *Store) Receipt(id string) (*Receipt, bool, error) {
639		state, err := s.readState()
640		if err != nil {
641			return nil, false, err
642		}
643		r := findReceipt(state.Receipts, id)
644		if r == nil {
645			return nil, false, nil
646		}
647		return cloneReceipt(r), true, nil
648	}
649	
650	// Receipts 按成功提交的先后顺序返回全部执行凭据的副本。
651	func (s *Store) Receipts() ([]*Receipt, error) {
652		state, err := s.readState()
653		if err != nil {
654			return nil, err
655		}
656		out := make([]*Receipt, 0, len(state.Receipts))
657		for _, r := range state.Receipts {
658			out = append(out, cloneReceipt(r))
659		}
660		return out, nil
661	}
662	
663	func (s *Store) readState() (*storedState, error) {
664		commit, err := s.begin()
665		if err != nil {
666			return nil, err
667		}
668		defer commit()
669		return s.loadLocked()
670	}
