901	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
902	
903	// schemaKind 是状态文件 JSON 在某一层的形状类别。
904	type schemaKind int
905	
906	const (
907		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
908		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
909		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
910		kindArray                     // 数组
911		kindString                    // 叶子：必须是 JSON 字符串
912		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
913		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
914	)
915	
916	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
917	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
918	type schemaNode struct {
919		kind   schemaKind
920		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
921		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
922	}
923	
924	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
925	func schemaOf(t reflect.Type) *schemaNode {
926		for t.Kind() == reflect.Pointer {
927			t = t.Elem()
928		}
929		switch t.Kind() {
930		case reflect.Struct:
931			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
932			for i := 0; i < t.NumField(); i++ {
933				f := t.Field(i)
934				if f.PkgPath != "" { // 未导出字段不参与 JSON
935					continue
936				}
937				name := f.Name
938				if tag, ok := f.Tag.Lookup("json"); ok {
939					tagName, _, _ := strings.Cut(tag, ",")
940					if tagName == "-" {
941						continue
942					}
943					if tagName != "" {
944						name = tagName
945					}
946				}
947				node.fields[name] = schemaOf(f.Type)
948			}
949			return node
950		case reflect.Map:
951			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
952		case reflect.Slice, reflect.Array:
953			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
954		case reflect.String:
955			return &schemaNode{kind: kindString}
956		case reflect.Bool:
957			return &schemaNode{kind: kindBoolean}
958		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
959			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
960			return &schemaNode{kind: kindInteger}
961		default:
962			return &schemaNode{kind: kindAny}
963		}
964	}
965	
966	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
967	
968	func init() {
969		// 票据的四个标量字段（representative/weight/support/voted_at）由
970		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
971		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
972		// 不抢在解码器之前用不含票据定位的通用信息报错。
973		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
974		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
975			ballotFields[name].kind = kindAny
976		}
977		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
978		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
979		// 叶子位置保持宽松。
980		storedStateSchema.fields["receipts"].elem.fields["executed_at"].kind = kindAny
981	}
982	
983	// scanFrame 是结构扫描的栈帧。
984	type scanFrame struct {
985		node    *schemaNode
986		isArray bool
987		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
988		seen    map[string]bool
989		atValue bool // 对象帧：下一个待消费 token 是值而非键
990		index   int  // 数组帧：下一个元素下标
991		path    string
992	}
993	
994	func peekFrame(stack []*scanFrame) *scanFrame {
995		if len(stack) == 0 {
996			return nil
997		}
998		return stack[len(stack)-1]
999	}
1000	
1001	// checkStateStructure 在解码前逐 token 扫描状态文件：
1002	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1003	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1004	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1005	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1006	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1007	//
1008	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1009	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1010	func checkStateStructure(raw []byte) error {
1011		dec := json.NewDecoder(bytes.NewReader(raw))
1012		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1013		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1014		dec.UseNumber()
1015		var stack []*scanFrame
1016		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1017		pendingNode := storedStateSchema
1018		pendingPath := "state"
1019	
1020		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1021		finishValue := func() {
1022			top := peekFrame(stack)
1023			if top == nil || top.opaque {
1024				return
1025			}
1026			if top.isArray {
1027				top.index++
1028			} else {
1029				top.atValue = false
1030			}
1031		}
1032	
1033		for {
1034			tok, err := dec.Token()
1035			if err == io.EOF {
1036				if len(stack) != 0 {
1037					return errors.New("unterminated object or array")
1038				}
1039				return nil
1040			}
1041			if err != nil {
1042				return err
1043			}
1044	
1045			if top := peekFrame(stack); top != nil && top.opaque {
1046				// 不透明容器内不做字段检查，只配对括号。
1047				if d, ok := tok.(json.Delim); ok {
1048					if d == '{' || d == '[' {
1049						stack = append(stack, &scanFrame{opaque: true})
1050					} else {
1051						stack = stack[:len(stack)-1]
1052						finishValue()
1053					}
1054				}
1055				continue
1056			}
1057	
1058			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1059				// 对象帧的键位置：闭括号或下一个键。
1060				if d, ok := tok.(json.Delim); ok {
1061					if d != '}' {
1062						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1063					}
1064					stack = stack[:len(stack)-1]
1065					finishValue()
1066					continue
1067				}
1068				key, ok := tok.(string)
1069				if !ok {
1070					return errors.New("object key must be a string")
1071				}
1072				if top.seen[key] {
1073					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1074				}
1075				top.seen[key] = true
1076				top.atValue = true
1077				switch top.node.kind {
1078				case kindObject:
1079					child, known := top.node.fields[key]
1080					if !known {
1081						return fmt.Errorf("unknown field %q at %s", key, top.path)
1082					}
1083					pendingNode = child
1084					pendingPath = top.path + "." + key
1085				case kindMap:
1086					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1087					pendingNode = top.node.elem
1088					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1089				}
1090				continue
1091			}
1092	
1093			// 值位置：对象键之后的值或数组元素。
1094			node := pendingNode
1095			path := pendingPath
1096			if top := peekFrame(stack); top != nil && top.isArray {
1097				node = top.node.elem
1098				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1099			}
1100			if d, ok := tok.(json.Delim); ok {
1101				switch d {
1102				case '{', '[':
1103					frame := &scanFrame{isArray: d == '[', path: path}
1104					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1105						(d == '[' && node.kind == kindArray)
1106					if !shapeOK {
1107						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1108						frame.opaque = true
1109					} else {
1110						frame.node = node
1111						if d == '{' {
1112							frame.seen = map[string]bool{}
1113						}
1114					}
1115					stack = append(stack, frame)
1116				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1117					if len(stack) == 0 {
1118						return errors.New("unexpected closing delimiter")
1119					}
1120					stack = stack[:len(stack)-1]
1121					finishValue()
1122				}
1123				continue
1124			}
1125			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1126			// null 不允许用来顶替字符串/布尔/整数。
1127			if err := checkLeafScalar(node, path, tok); err != nil {
1128				return err
1129			}
1130			finishValue()
1131		}
1132	}
1133	
1134	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1135	func leafKindName(k schemaKind) string {
1136		switch k {
1137		case kindString:
1138			return "string"
1139		case kindBoolean:
1140			return "boolean"
1141		case kindInteger:
1142			return "integer"
1143		default:
1144			return "value"
1145		}
1146	}
1147	
1148	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1149	func tokenKindName(tok json.Token) string {
1150		switch v := tok.(type) {
1151		case nil:
1152			return "null"
1153		case string:
1154			return "string"
1155		case bool:
1156			return "boolean"
1157		case json.Number:
1158			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1159				return "integer"
1160			}
1161			return "number"
1162		default:
1163			return "value"
1164		}
1165	}
1166	
1167	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1168	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1169	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1170		switch node.kind {
1171		case kindString, kindBoolean, kindInteger:
1172		default:
1173			return nil
1174		}
1175		if node.kind == kindInteger {
1176			if n, ok := tok.(json.Number); ok {
1177				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1178					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1179				}
1180				return nil
1181			}
1182		}
1183		want := leafKindName(node.kind)
1184		if got := tokenKindName(tok); got != want {
1185			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1186		}
1187		return nil
1188	}
1189

