217	// memberList 收集重复的 --member ID:WEIGHT 参数，保持提交顺序。
218	type memberList []govflow.VoteMember
219	
220	func (m *memberList) String() string { return fmt.Sprint([]govflow.VoteMember(*m)) }
221	func (m *memberList) Set(v string) error {
222		id, weight, err := splitMember(v)
223		if err != nil {
224			return err
225		}
226		*m = append(*m, govflow.VoteMember{ID: id, Weight: weight})
227		return nil
228	}
229	
230	func splitMember(raw string) (string, int64, error) {
231		idx := strings.LastIndex(raw, ":")
232		if idx <= 0 || idx == len(raw)-1 {
233			return "", 0, fmt.Errorf("malformed member %q, expected ID:WEIGHT", raw)
234		}
235		id := raw[:idx]
236		weight, err := strconv.ParseInt(raw[idx+1:], 10, 64)
237		if err != nil {
238			return "", 0, fmt.Errorf("malformed member %q: weight must be int64: %v", raw, err)
239		}
240		return id, weight, nil
241	}
242	
243	// delegationList 收集重复的 --delegate FROM:TO 参数，保持提交顺序。
244	type delegationList []govflow.Delegation
245	
246	func (d *delegationList) String() string { return fmt.Sprint([]govflow.Delegation(*d)) }
247	func (d *delegationList) Set(v string) error {
248		from, to, ok := strings.Cut(v, ":")
249		if !ok || from == "" || to == "" {
250			return fmt.Errorf("malformed delegation %q, expected FROM:TO", v)
251		}
252		*d = append(*d, govflow.Delegation{From: from, To: to})
253		return nil
254	}
